import { useEffect, useId, useMemo, useRef, useState } from "react";
import {
  Avatar,
  Badge,
  Button,
  Checkbox,
  Heading,
  Input,
  Progress,
  Select,
  Stat,
  Sparkline,
  Switch,
  Table,
  Text,
} from "@paraxe/react";
import {
  dashboardDate,
  dashboardDay,
  dashboardScopes,
  dashboardView,
  projectStatusLabels,
  projectStatuses,
  projectStatusTone,
  sampleDashboard,
  validateDashboard,
  type Dashboard01Props,
  type DashboardProject,
  type DashboardScope,
  type ProjectStatus,
} from "../shared/dashboard";
import "../shared/dashboard.css";
const columns = [
  { key: "title", label: "Project", sortable: true },
  { key: "ownerName", label: "Owner", sortable: true },
  { key: "statusLabel", label: "Health", sortable: true },
  { key: "progressPercent", label: "Delivery", sortable: true },
  { key: "due", label: "Due", sortable: true },
];
export function Dashboard01({
  snapshot = sampleDashboard,
  title = "Your workspace, in focus.",
  description = "A clear view of the work, the people, and what needs you next.",
  locale = "en-GB",
  loading = false,
  error,
  retry,
  refresh,
  createProject,
  openProject,
  updateTask,
}: Dashboard01Props) {
  const id = `dashboard-${useId()}`,
    data = useMemo(() => validateDashboard(snapshot), [snapshot]);
  const [scope, setScope] = useState<DashboardScope>("all"),
    [query, setQuery] = useState(""),
    [status, setStatus] = useState<ProjectStatus | "all">("all"),
    [showCompleted, setShowCompleted] = useState(false),
    [allPriorities, setAllPriorities] = useState(false);
  const [pending, setPending] = useState<string | null>(null),
    [feedback, setFeedback] = useState<{
      text: string;
      failed?: string;
    } | null>(null);
  const busy = useRef(false),
    generation = useRef(0),
    workspace = useRef(data.id);
  useEffect(() => {
    generation.current++;
    busy.current = false;
    setPending(null);
    setFeedback(null);
    setScope("all");
    setQuery("");
    setStatus("all");
    setShowCompleted(false);
    setAllPriorities(false);
    return () => {
      generation.current++;
      busy.current = false;
    };
  }, [data.id]);
  workspace.current = data.id;
  const view = dashboardView(data, scope, query, status, showCompleted),
    locked = loading || !!error || !!pending;
  async function run(key: string, operation: () => void | Promise<void>) {
    if (busy.current || loading || error) return;
    busy.current = true;
    setPending(key);
    setFeedback(null);
    const request = ++generation.current,
      origin = data.id;
    try {
      await operation();
      if (request === generation.current && origin === workspace.current)
        setFeedback({
          text: key.startsWith("task-") ? "Task updated." : "Project opened.",
        });
    } catch {
      if (request === generation.current && origin === workspace.current)
        setFeedback({
          text: "That change could not be completed. Please try again.",
          failed: key,
        });
    } finally {
      if (request === generation.current && origin === workspace.current) {
        busy.current = false;
        setPending(null);
      }
    }
  }
  const person = (memberId: string) =>
    data.members.find((member) => member.id === memberId)!;
  const project = (projectId: string) =>
    data.projects.find((item) => item.id === projectId)!;
  const date = (value: string, time = false) =>
    dashboardDate(value, locale, time);
  function projectTitle(item: DashboardProject) {
    return openProject ? (
      <Button
        variant="text"
        disabled={locked}
        onActivate={() =>
          run(`project-${item.id}`, () => openProject({ ...item }))
        }
      >
        {item.title}
      </Button>
    ) : item.href ? (
      <a
        href={locked ? undefined : item.href}
        aria-disabled={locked || undefined}
      >
        {item.title}
      </a>
    ) : (
      <strong>{item.title}</strong>
    );
  }
  return (
    <section
      className="dashboard01"
      aria-labelledby={`${id}-title`}
      aria-busy={loading || !!pending || undefined}
    >
      <header className="dashboard01-header">
        <div>
          <p className="dashboard01-eyebrow">
            {loading || error ? "Workspace overview" : data.organization} /
            Overview
          </p>
          <Heading level="h1" id={`${id}-title`}>
            {title}
          </Heading>
          <Text>{description}</Text>
        </div>
        <div className="dashboard01-header-actions">
          {refresh && (
            <Button variant="secondary" disabled={locked} onActivate={refresh}>
              Refresh overview
            </Button>
          )}
          {createProject && (
            <Button disabled={locked} onActivate={createProject}>
              New project <span aria-hidden="true">+</span>
            </Button>
          )}
        </div>
      </header>
      {loading || error ? (
        <div className="dashboard01-state" role={error ? "alert" : "status"}>
          <Heading level="h2">
            {error
              ? "We could not load your workspace."
              : "Preparing your overview…"}
          </Heading>
          <Text>
            {error || "Your projects and priorities will appear here."}
          </Text>
          {error && retry && <Button onActivate={retry}>Try again</Button>}
        </div>
      ) : (
        <>
          <div className="dashboard01-context">
            <label>
              Viewing{" "}
              <Select
                modelValue={scope}
                disabled={!!pending}
                onModelValueChange={(value) =>
                  setScope(value as DashboardScope)
                }
              >
                {dashboardScopes.map((item) => (
                  <option key={item.value} value={item.value}>
                    {item.label}
                  </option>
                ))}
              </Select>
            </label>
            <p>
              Snapshot{" "}
              <time dateTime={data.asOf}>{date(data.asOf, true)} UTC</time>
            </p>
          </div>
          {feedback && (
            <p
              id={`${id}-feedback`}
              className="dashboard01-feedback"
              role={feedback.failed ? "alert" : "status"}
            >
              {feedback.text}
            </p>
          )}

          <div className="dashboard01-overview-grid">
            <section
              className="dashboard01-overview"
              aria-labelledby={`${id}-pulse`}
            >
              <div className="dashboard01-overview-title">
                <p className="dashboard01-eyebrow" id={`${id}-pulse`}>
                  01 / Performance overview
                </p>
                <Badge>Delivery</Badge>
              </div>
              <div className="dashboard01-pulse">
                <div className="dashboard01-completion">
                  <Stat
                    variant="plain"
                    label="Work completed"
                    value={view.total ? `${view.percentage}%` : "—"}
                  />
                  <p>
                    {view.completed} of {view.total} deliverables
                  </p>
                  {view.total > 0 && (
                    <Progress
                      label="Overall delivery"
                      value={view.completed}
                      max={view.total}
                    />
                  )}
                </div>

                <div className="dashboard01-trend">
                  <div className="dashboard01-trend-heading">
                    <h3>Delivery over time</h3>
                    <span>Completed / total scope</span>
                  </div>
                  {view.trend.length > 1 && view.total > 0 ? (
                    <>
                      <div className="dashboard01-trend-plot">
                        <div
                          className="dashboard01-trend-scale"
                          aria-hidden="true"
                        >
                          <span>100%</span>
                          <span>50%</span>
                          <span>0%</span>
                        </div>
                        <div className="dashboard01-trend-lines">
                          <Sparkline
                            data={view.trend.map((point) => point.percentage)}
                            min={0}
                            max={100}
                            width={640}
                            height={200}
                            variant="area"
                            color="var(--brand-primary)"
                            label="Completed deliverables as a percentage of project scope over the supplied reporting dates"
                          />
                        </div>
                      </div>
                      <div
                        className="dashboard01-trend-dates"
                        aria-hidden="true"
                      >
                        {view.trendTicks.map(({ point, index }) => (
                          <span
                            key={point.date}
                            style={{
                              left: `${(index / (view.trend.length - 1)) * 100}%`,
                            }}
                          >
                            {new Intl.DateTimeFormat(locale, {
                              day: "numeric",
                              month: "short",
                              timeZone: "UTC",
                            }).format(new Date(point.date))}
                          </span>
                        ))}
                      </div>
                      <details className="dashboard01-trend-data">
                        <summary>View reporting data</summary>
                        <table>
                          <caption>
                            Delivery history for this workspace view
                          </caption>
                          <thead>
                            <tr>
                              <th scope="col">Reporting date</th>
                              <th scope="col">Completed</th>
                              <th scope="col">Scope</th>
                            </tr>
                          </thead>
                          <tbody>
                            {view.trend.map((point) => (
                              <tr key={point.date}>
                                <th scope="row">{date(point.date)}</th>
                                <td>{point.completed}</td>
                                <td>{point.total}</td>
                              </tr>
                            ))}
                          </tbody>
                        </table>
                      </details>
                    </>
                  ) : (
                    <p className="dashboard01-trend-empty">
                      Supply at least two reporting dates to see delivery
                      history.
                    </p>
                  )}
                </div>
              </div>
              <div className="dashboard01-metrics">
                <div>
                  <Stat
                    variant="plain"
                    label="Active projects"
                    value={view.active}
                  />
                  <p>In this workspace view</p>
                </div>
                <div>
                  <Stat
                    variant="plain"
                    label="Needs attention"
                    value={view.attention}
                  />
                  <p>At risk, blocked, or overdue</p>
                </div>
                <div>
                  <Stat
                    variant="plain"
                    label="Due in the next 7 days"
                    value={view.dueSoon}
                  />
                  <p>Includes today · excludes overdue</p>
                </div>
              </div>
            </section>
            <section
              className="dashboard01-panel dashboard01-priorities"
              aria-labelledby={`${id}-priorities`}
            >
              <div className="dashboard01-panel-head">
                <div>
                  <p className="dashboard01-eyebrow">02 / Your next moves</p>
                  <Heading level="h2" id={`${id}-priorities`}>
                    First things first.
                  </Heading>
                </div>
                <Badge>
                  {updateTask ? `${view.pendingTasks} open` : "View only"}
                </Badge>
              </div>
              <ul className="dashboard01-tasks" id={`${id}-tasks`}>
                {view.priorities
                  .slice(0, allPriorities ? undefined : 3)
                  .map((task) => (
                    <li
                      key={task.id}
                      className={
                        task.done ? "dashboard01-task--done" : undefined
                      }
                    >
                      <Checkbox
                        id={`${id}-task-${task.id}`}
                        modelValue={task.done}
                        disabled={locked || !updateTask}
                        invalid={feedback?.failed === `task-${task.id}`}
                        describedBy={`${id}-task-${task.id}-meta${feedback?.failed === `task-${task.id}` ? ` ${id}-feedback` : ""}`}
                        onModelValueChange={(done) =>
                          updateTask &&
                          run(`task-${task.id}`, () =>
                            updateTask(task.id, done),
                          )
                        }
                      >
                        {task.title}
                      </Checkbox>
                      <p id={`${id}-task-${task.id}-meta`}>
                        {project(task.projectId).title} ·{" "}
                        <time dateTime={task.due}>{date(task.due)}</time>
                        {task.priority === "high" && " · High priority"}
                      </p>
                    </li>
                  ))}
              </ul>
              {!view.priorities.length && (
                <Text>No priorities to show in this view.</Text>
              )}
              <div className="dashboard01-task-footer">
                <Switch
                  modelValue={showCompleted}
                  onModelValueChange={(value) => {
                    setShowCompleted(value);
                    if (value) setAllPriorities(true);
                  }}
                >
                  Show completed
                </Switch>
                {view.priorities.length > 3 && (
                  <Button
                    variant="text"
                    size="small"
                    aria-expanded={allPriorities}
                    aria-controls={`${id}-tasks`}
                    onActivate={() => setAllPriorities(!allPriorities)}
                  >
                    {allPriorities
                      ? "Show fewer"
                      : `View all ${view.priorities.length}`}
                  </Button>
                )}
              </div>
            </section>
          </div>
          <section
            className="dashboard01-panel dashboard01-projects"
            aria-labelledby={`${id}-projects`}
          >
            <div className="dashboard01-panel-head">
              <div>
                <p className="dashboard01-eyebrow">03 / Project register</p>
                <Heading level="h2" id={`${id}-projects`}>
                  The work, at a glance.
                </Heading>
              </div>
              <Badge>{view.projects.length} projects</Badge>
            </div>
            {view.projects.length > 0 && (
              <div className="dashboard01-health">
                <h3>Portfolio health</h3>
                <p className="dashboard01-health-summary">
                  {view.projects.length} projects. {view.attention} need
                  attention.
                </p>
                <div className="dashboard01-health-bar" aria-hidden="true">
                  {view.distribution
                    .filter((item) => item.count)
                    .map((item) => (
                      <span
                        key={item.status}
                        className={`dashboard01-health--${item.status}`}
                        style={{
                          width: `${(item.count / view.projects.length) * 100}%`,
                        }}
                      />
                    ))}
                </div>
                <ul className="dashboard01-legend">
                  {view.distribution.map((item) => (
                    <li key={item.status}>
                      <span
                        className={`dashboard01-dot dashboard01-health--${item.status}`}
                        aria-hidden="true"
                      />
                      {item.label}
                      <strong>{item.count}</strong>
                    </li>
                  ))}
                </ul>
              </div>
            )}
            <div className="dashboard01-filters">
              <label>
                Find a project
                <Input
                  modelValue={query}
                  placeholder="Project, client, or owner"
                  onModelValueChange={setQuery}
                />
              </label>
              <label>
                Project health
                <Select
                  modelValue={status}
                  onModelValueChange={(value) =>
                    setStatus(value as ProjectStatus | "all")
                  }
                >
                  <option value="all">All health statuses</option>
                  {projectStatuses.map((value) => (
                    <option key={value} value={value}>
                      {projectStatusLabels[value]}
                    </option>
                  ))}
                </Select>
              </label>
            </div>
            <Table
              columns={columns}
              rows={view.rows}
              sortable
              caption="Projects in the selected workspace view"
              emptyText={
                view.projects.length
                  ? "No projects match your filters."
                  : "No projects in this view yet."
              }
              renderCell={(column, row) =>
                column.key === "title" ? (
                  <div className="dashboard01-project-name">
                    <span>
                      {row.code} / {row.client}
                    </span>
                    {projectTitle(row)}
                  </div>
                ) : column.key === "ownerName" ? (
                  <div className="dashboard01-owner">
                    <Avatar
                      alt=""
                      name={row.ownerName}
                      src={person(row.ownerId).src}
                      size="sm"
                    />
                    <span>{row.ownerName}</span>
                  </div>
                ) : column.key === "statusLabel" ? (
                  <Badge variant={projectStatusTone(row.status)}>
                    {row.statusLabel}
                  </Badge>
                ) : column.key === "progressPercent" ? (
                  <div className="dashboard01-progress">
                    <Progress
                      label={`${row.title} delivery`}
                      value={row.completed}
                      max={row.total}
                    />
                    <span>
                      {row.completed}/{row.total} · {row.progressPercent}%
                    </span>
                  </div>
                ) : (
                  <div className="dashboard01-due">
                    <time dateTime={row.due}>{date(row.due)}</time>
                    {row.status !== "complete" &&
                      row.due < dashboardDay(data.asOf) && <span>Overdue</span>}
                  </div>
                )
              }
            />
            {(query || status !== "all") && (
              <div className="dashboard01-table-foot">
                <Text>
                  {view.rows.length} of {view.projects.length} projects ·
                  Summary follows workspace scope
                </Text>
                <Button
                  variant="text"
                  onActivate={() => {
                    setQuery("");
                    setStatus("all");
                  }}
                >
                  Clear filters
                </Button>
              </div>
            )}
          </section>
          <section
            className="dashboard01-panel dashboard01-deadlines"
            aria-labelledby={`${id}-deadlines`}
          >
            <p className="dashboard01-eyebrow">Coming up</p>
            <Heading level="h2" id={`${id}-deadlines`}>
              Next handovers.
            </Heading>
            <ol>
              {view.deadlines.map((item) => (
                <li key={item.id}>
                  <div>
                    <time dateTime={item.due}>{date(item.due)}</time>
                    {item.due < dashboardDay(data.asOf) && (
                      <Badge variant="warning">Overdue</Badge>
                    )}
                  </div>
                  {projectTitle(item)}
                  <p>{item.client}</p>
                </li>
              ))}
            </ol>
            {!view.deadlines.length && (
              <Text>No upcoming handovers in this view.</Text>
            )}
          </section>
          <div className="dashboard01-support">
            <section
              className="dashboard01-panel dashboard01-activity"
              aria-labelledby={`${id}-activity`}
            >
              <div className="dashboard01-panel-head">
                <div>
                  <p className="dashboard01-eyebrow">04 / Team journal</p>
                  <Heading level="h2" id={`${id}-activity`}>
                    While you were working.
                  </Heading>
                </div>
                <Text>Latest updates</Text>
              </div>
              <ol>
                {view.activity.map((event) => (
                  <li key={event.id}>
                    <Avatar
                      alt=""
                      name={
                        event.actorId ? person(event.actorId).name : "Workspace"
                      }
                      src={
                        event.actorId ? person(event.actorId).src : undefined
                      }
                      size="sm"
                    />
                    <div>
                      <p>
                        <strong>
                          {event.actorId
                            ? person(event.actorId).name
                            : "Workspace"}
                        </strong>{" "}
                        {event.action}
                      </p>
                      <p>
                        {event.projectId &&
                          `${project(event.projectId).title} · `}
                        <time dateTime={event.at}>
                          {date(event.at, true)} UTC
                        </time>
                      </p>
                    </div>
                  </li>
                ))}
              </ol>
              {!view.activity.length && (
                <Text>No recent activity in this view.</Text>
              )}
            </section>
            <section
              className="dashboard01-panel dashboard01-people"
              aria-labelledby={`${id}-people`}
            >
              <p className="dashboard01-eyebrow">05 / Ownership</p>
              <Heading level="h2" id={`${id}-people`}>
                People behind the work.
              </Heading>
              <ul>
                {view.ownership.map((member) => (
                  <li key={member.id}>
                    <Avatar alt="" name={member.name} src={member.src} />
                    <div>
                      <strong>{member.name}</strong>
                      <p>{member.role}</p>
                    </div>
                    <span>{member.active} active</span>
                  </li>
                ))}
              </ul>
              {!view.ownership.length && (
                <Text>Project owners will appear here.</Text>
              )}
            </section>
          </div>
        </>
      )}
    </section>
  );
}

export type ProjectStatus = "on-track" | "at-risk" | "blocked" | "complete";
export type DashboardScope = "all" | "mine" | "attention";
export interface DashboardMember {
  id: string;
  name: string;
  role: string;
  src?: string;
}
export interface DashboardProject {
  id: string;
  code: string;
  title: string;
  client: string;
  summary: string;
  ownerId: string;
  status: ProjectStatus;
  completed: number;
  total: number;
  due: string;
  href?: string;
}
export interface DashboardTask {
  id: string;
  title: string;
  projectId: string;
  assigneeId?: string;
  due: string;
  priority: "high" | "normal";
  done: boolean;
}
export interface DashboardActivity {
  id: string;
  actorId?: string;
  projectId?: string;
  action: string;
  at: string;
}
export interface DashboardHistoryPoint {
  date: string;
  projects: readonly { projectId: string; completed: number; total: number }[];
}
export interface DashboardSnapshot {
  id: string;
  organization: string;
  asOf: string;
  currentMemberId: string;
  members: readonly DashboardMember[];
  projects: readonly DashboardProject[];
  tasks: readonly DashboardTask[];
  activity: readonly DashboardActivity[];
  history?: readonly DashboardHistoryPoint[];
}
export interface Dashboard01Props {
  snapshot?: DashboardSnapshot;
  title?: string;
  description?: string;
  locale?: string;
  loading?: boolean;
  error?: string;
  retry?: () => void;
  refresh?: () => void;
  createProject?: () => void;
  openProject?: (project: DashboardProject) => void | Promise<void>;
  updateTask?: (id: string, done: boolean) => void | Promise<void>;
}
export const projectStatuses: readonly ProjectStatus[] = [
  "on-track",
  "at-risk",
  "blocked",
  "complete",
];
export const projectStatusLabels: Record<ProjectStatus, string> = {
  "on-track": "On track",
  "at-risk": "At risk",
  blocked: "Blocked",
  complete: "Complete",
};
export const projectStatusTone = (status: ProjectStatus) =>
  status === "on-track"
    ? "success"
    : status === "at-risk"
      ? "warning"
      : status === "blocked"
        ? "danger"
        : "brand";
export const dashboardScopes: readonly {
  value: DashboardScope;
  label: string;
}[] = [
  { value: "all", label: "Whole workspace" },
  { value: "mine", label: "My work" },
  { value: "attention", label: "Needs attention" },
];
export function dashboardDay(value: string) {
  return new Date(value).toISOString().slice(0, 10);
}
export function dashboardDate(
  value: string,
  locale = "en-GB",
  withTime = false,
) {
  return new Intl.DateTimeFormat(locale, {
    day: "numeric",
    month: "short",
    year: "numeric",
    ...(withTime ? { hour: "2-digit", minute: "2-digit" } : {}),
    timeZone: "UTC",
  }).format(new Date(value));
}
export const projectPercent = (project: DashboardProject) =>
  Math.round((project.completed / project.total) * 100);
export const projectNeedsAttention = (
  project: DashboardProject,
  asOf: string,
) =>
  project.status === "at-risk" ||
  project.status === "blocked" ||
  (project.status !== "complete" && project.due < dashboardDay(asOf));
const realDay = (value: string) =>
  typeof value === "string" &&
  /^\d{4}-\d{2}-\d{2}$/.test(value) &&
  Number.isFinite(Date.parse(value)) &&
  dashboardDay(value) === value;
const realInstant = (value: string) =>
  typeof value === "string" &&
  /T.*(?:Z|[+-]\d{2}:\d{2})$/.test(value) &&
  realDay(value.slice(0, 10)) &&
  Number.isFinite(Date.parse(value));
export function validateDashboard(input: DashboardSnapshot): DashboardSnapshot {
  const id = (value: string) =>
    typeof value === "string" && /^[a-zA-Z0-9][a-zA-Z0-9_-]*$/.test(value);
  const memberIds = new Set<string>(),
    projectIds = new Set<string>(),
    taskIds = new Set<string>(),
    activityIds = new Set<string>();
  if (!id(input.id) || !input.organization?.trim() || !realInstant(input.asOf))
    throw Error(
      "Dashboard needs a workspace ID, name and explicit snapshot timestamp.",
    );
  const members = input.members.map((member) => {
    if (!id(member.id) || memberIds.has(member.id) || !member.name?.trim())
      throw Error("Members require unique IDs and names.");
    memberIds.add(member.id);
    return { ...member };
  });
  if (!memberIds.has(input.currentMemberId))
    throw Error("The current member must be present in the workspace.");
  let total = 0,
    completed = 0;
  const projects = input.projects.map((project) => {
    if (
      !id(project.id) ||
      projectIds.has(project.id) ||
      !project.title?.trim() ||
      !project.code?.trim() ||
